async(page)=>{
await page.locator('#maxwell-preset').selectOption('relaxation');
const stages=await page.evaluate(()=>{
 const get=()=>document.querySelector('#maxwell-status').textContent;
 document.querySelector('#maxwell-run').click();const first=get();
 const p=document.querySelector('#maxwell-parameters');p.value='[20000000,12000000,48000000]';p.dispatchEvent(new Event('input',{bubbles:true}));const edited=get();
 const cleared=document.querySelector('#maxwell-export').disabled;
 document.querySelector('#maxwell-run').click();return {first,edited,cleared,second:get()};
});
await page.waitForFunction(()=>document.querySelector('#maxwell-status').textContent==='Physical-time history complete.');
const download=page.waitForEvent('download');await page.locator('#maxwell-export').click();
await (await download).saveAs('/private/tmp/atlas-maxwell-main-atlas-v1/browser-latest-request.json');
return {stages,final:await page.locator('#maxwell-status').textContent(),url:page.url(),export:'/private/tmp/atlas-maxwell-main-atlas-v1/browser-latest-request.json',claim:'Actual same-model edit cancels running request and replacement completes; does not assert stale callback arrived after termination.'};
}

